package vn.xuannhashop.business.payroll.application;
import java.util.*;import java.time.YearMonth;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import vn.xuannhashop.business.shared.*;import vn.xuannhashop.business.shared.security.ActorContext;import vn.xuannhashop.business.shared.audit.ActivityService;
import vn.xuannhashop.business.finance.application.FinanceApplication;
@Service public class PayrollExtrasService implements PayrollExtrasApplication {
    private final PayrollExtrasRepository r;private final PayrollRepository payroll;private final FinanceApplication finance;private final ActorContext actor;private final Commands commands;private final ActivityService audit;
    public PayrollExtrasService(PayrollExtrasRepository r,PayrollRepository payroll,FinanceApplication finance,ActorContext actor,Commands commands,ActivityService audit){this.r=r;this.payroll=payroll;this.finance=finance;this.actor=actor;this.commands=commands;this.audit=audit;}
    public Map<String,Object> overview(){actor.require("OWNER","ACCOUNTANT");return r.overview();}
    public Map<String,Object> mine(){if(actor.current().role().equals("CUSTOMER"))throw DomainException.forbidden();return r.mine(actor.current().id());}
    @Transactional public UUID link(UUID staff,UUID account,String key){actor.require("OWNER");if(staff==null||account==null)throw DomainException.bad("Chọn hồ sơ và tài khoản.");return commands.once(key,"STAFF_LINK:"+staff+":"+account,()->{var p=payroll.lockStaff(staff);if(p==null)throw DomainException.missing();if(p.get("user_id")!=null)throw DomainException.conflict("Hồ sơ đã liên kết tài khoản; không thể tự chuyển quyền xem lương.");if(!r.linkable(account))throw DomainException.bad("Chọn tài khoản nhân viên đang hoạt động, chưa liên kết.");r.link(staff,account);audit.record("STAFF_ACCOUNT_LINKED",staff,"account="+account);return staff;});}
    @Transactional public UUID adjustment(Adjustment c,String key){actor.require("OWNER","ACCOUNTANT");if(c==null||c.staffId()==null||c.kind()==null||!Set.of("ALLOWANCE","BONUS","DEDUCTION","ADVANCE").contains(c.kind()))throw DomainException.bad("Loại khoản lương không hợp lệ.");try{YearMonth.parse(c.period());}catch(Exception ex){throw DomainException.bad("Kỳ có dạng YYYY-MM.");}Checks.money(c.amount());Checks.text(c.basis(),1000,"Căn cứ khoản lương");return commands.once(key,"PAYROLL_ADJUSTMENT:"+c,()->{if(payroll.lockStaff(c.staffId())==null)throw DomainException.missing();if(payroll.periodLocked(c.staffId(),c.period()))throw DomainException.conflict("Kỳ đã lập bảng lương, không được thêm khoản.");UUID id=UUID.randomUUID();r.adjustment(id,c,actor.username());audit.record("PAYROLL_ADJUSTMENT_REQUESTED",id,c.kind()+"; "+c.period());return id;});}
    @Transactional public void decide(UUID id,boolean accepted,String note,String key){actor.require("OWNER","ACCOUNTANT");Checks.text(note,1000,"Căn cứ quyết định / chứng từ chi tạm ứng");commands.once(key,"PAYROLL_ADJUSTMENT_DECIDE:"+id+":"+accepted+":"+note,()->{var c=r.adjustment(id);if(c==null)throw DomainException.missing();if(!c.get("status").equals("PENDING")||c.get("requested_by").equals(actor.username()))throw DomainException.conflict("Khoản phải chờ duyệt bởi người khác.");UUID staff=(UUID)c.get("staff_id");payroll.lockStaff(staff);if(payroll.periodLocked(staff,(String)c.get("period")))throw DomainException.conflict("Kỳ đã chốt.");if(accepted&&c.get("kind").equals("ADVANCE"))finance.payAdvance(id,(java.math.BigDecimal)c.get("amount"),note,"payroll-advance:"+id);r.decide(id,accepted,actor.username(),note);audit.record("PAYROLL_ADJUSTMENT_DECIDED",id,accepted+"; "+note);return id;});}
    @Transactional public UUID question(UUID payroll,String question,String key){if(actor.current().role().equals("CUSTOMER"))throw DomainException.forbidden();Checks.text(question,1000,"Nội dung đối chiếu lương");return commands.once(key,"PAYROLL_QUESTION:"+payroll+":"+question,()->{if(!r.owns(actor.current().id(),payroll))throw DomainException.missing();UUID id=UUID.randomUUID();r.question(id,payroll,question,actor.username());audit.record("PAYROLL_QUESTION_CREATED",id,"Yêu cầu đối chiếu phiếu lương");return id;});}
    @Transactional public void answer(UUID id,String answer,String key){actor.require("OWNER","ACCOUNTANT");Checks.text(answer,1000,"Kết quả đối chiếu");commands.once(key,"PAYROLL_ANSWER:"+id+":"+answer,()->{var c=r.question(id);if(c==null)throw DomainException.missing();if(!c.get("status").equals("OPEN"))throw DomainException.conflict("Yêu cầu đã trả lời.");if(c.get("requested_by").equals(actor.username()))throw DomainException.conflict("Người trả lời phải khác người đề nghị.");r.answer(id,answer,actor.username());audit.record("PAYROLL_QUESTION_ANSWERED",id,"Đã phản hồi");return id;});}
}
